import { Capacitor } from '@capacitor/core'
import type { MoneyRepository } from './repository'
import { NativeSqliteMoneyRepository } from './native-sqlite-repository'
import { WebDexieMoneyRepository } from './web-dexie-repository'

let repository: MoneyRepository | undefined

export function createMoneyRepository(): MoneyRepository {
  return Capacitor.isNativePlatform() ? new NativeSqliteMoneyRepository() : new WebDexieMoneyRepository()
}

export function getMoneyRepository(): MoneyRepository {
  repository ??= createMoneyRepository()
  return repository
}

export function setMoneyRepositoryForTests(value: MoneyRepository | undefined): void {
  repository = value
}
