import Dexie, { type EntityTable } from 'dexie'
import type { Category, LedgerType } from '@/domain/models/category'
import { DEFAULT_SETTINGS, type AppSettings } from '@/domain/models/settings'
import type { TransactionRecord } from '@/domain/models/transaction'
import { DEFAULT_CATEGORIES } from '@/domain/services/category-seed'
import type { LedgerSnapshot, MoneyRepository } from './repository'

interface SettingRow {
  key: 'app'
  value: AppSettings
}

class MoneyDexieDatabase extends Dexie {
  categories!: EntityTable<Category, 'id'>
  transactions!: EntityTable<TransactionRecord, 'id'>
  settings!: EntityTable<SettingRow, 'key'>

  constructor(name: string) {
    super(name)
    this.version(1).stores({
      categories: 'id, type, parentId, isDefault, disabled, sortOrder',
      transactions: 'id, type, categoryId, bookedAt',
      settings: 'key',
    })
    // v2：Category 增加 color 可选字段；索引不变
    this.version(2).stores({
      categories: 'id, type, parentId, isDefault, disabled, sortOrder',
      transactions: 'id, type, categoryId, bookedAt',
      settings: 'key',
    }).upgrade(async () => {
      // 老数据库里所有内置一级分类回填默认色（color 字段原本不存在，初始全为 undefined）
      await this.categories
        .filter((category) => category.parentId === null && category.isDefault)
        .modify((category) => {
          const preset = DEFAULT_CATEGORIES.find((preset) => preset.id === category.id)
          if (preset?.color) category.color = preset.color
        })
    })
    // v3：内置二级分类补预设色（v2 只回填了一级，二级此前一律继承父色）；索引不变
    this.version(3).stores({
      categories: 'id, type, parentId, isDefault, disabled, sortOrder',
      transactions: 'id, type, categoryId, bookedAt',
      settings: 'key',
    }).upgrade(async () => {
      await this.categories
        .filter((category) => category.parentId !== null && category.isDefault && !category.color)
        .modify((category) => {
          const preset = DEFAULT_CATEGORIES.find((preset) => preset.id === category.id)
          if (preset?.color) category.color = preset.color
        })
    })
  }
}

export class WebDexieMoneyRepository implements MoneyRepository {
  private readonly db: MoneyDexieDatabase

  constructor(databaseName = 'money-app') {
    this.db = new MoneyDexieDatabase(databaseName)
  }

  async initialize(): Promise<void> {
    await this.db.open()
    await this.db.transaction('rw', this.db.categories, this.db.settings, async () => {
      if ((await this.db.categories.count()) === 0) await this.db.categories.bulkAdd(structuredClone([...DEFAULT_CATEGORIES]))
      if (!(await this.db.settings.get('app'))) await this.db.settings.put({ key: 'app', value: structuredClone(DEFAULT_SETTINGS) })
    })
  }

  async listTransactions(): Promise<TransactionRecord[]> {
    return this.db.transactions.orderBy('bookedAt').reverse().toArray()
  }

  async getTransaction(id: string): Promise<TransactionRecord | undefined> {
    return this.db.transactions.get(id)
  }

  async putTransaction(value: TransactionRecord): Promise<void> {
    const category = await this.db.categories.get(value.categoryId)
    if (!category || category.parentId === null || category.type !== value.type) throw new Error('账单必须选择同类型的有效二级分类')
    await this.db.transactions.put(JSON.parse(JSON.stringify(value)))
  }

  async deleteTransaction(id: string): Promise<void> {
    await this.db.transactions.delete(id)
  }

  async clearTransactions(): Promise<void> {
    await this.db.transactions.clear()
  }

  async listCategories(options: { type?: LedgerType; includeDisabled?: boolean } = {}): Promise<Category[]> {
    let values = await this.db.categories.toArray()
    if (options.type) values = values.filter((category) => category.type === options.type)
    if (!options.includeDisabled) values = values.filter((category) => !category.disabled)
    return values.sort((a, b) => Number(b.isDefault) - Number(a.isDefault) || a.sortOrder - b.sortOrder)
  }

  async getCategory(id: string): Promise<Category | undefined> {
    return this.db.categories.get(id)
  }

  async putCategory(value: Category): Promise<void> {
    if (value.parentId) {
      const parent = await this.db.categories.get(value.parentId)
      if (!parent || parent.parentId !== null || parent.type !== value.type) throw new Error('所属分类组不存在或类型不一致')
    }
    await this.db.categories.put(JSON.parse(JSON.stringify(value)))
  }

  async deleteCategory(id: string): Promise<void> {
    await this.db.transaction('rw', this.db.categories, this.db.transactions, async () => {
      if ((await this.db.transactions.where('categoryId').equals(id).count()) > 0) throw new Error('该分类仍有流水，不能直接删除')
      if ((await this.db.categories.where('parentId').equals(id).count()) > 0) throw new Error('请先处理一级分类下的二级分类')
      await this.db.categories.delete(id)
    })
  }

  async clearCustomCategories(): Promise<number> {
    return this.db.transaction('rw', this.db.categories, this.db.transactions, async () => {
      const custom = await this.db.categories.filter((category) => !category.isDefault).toArray()
      const ids = custom.map((category) => category.id)
      if (ids.length === 0) return 0
      const referenced = await this.db.transactions.where('categoryId').anyOf(ids).count()
      if (referenced > 0) throw new Error(`有 ${referenced} 条流水仍在使用自定义分类，请逐个迁移后再删除`)
      await this.db.categories.bulkDelete(ids)
      return ids.length
    })
  }

  async migrateTransactionsAndDelete(fromId: string, toId: string): Promise<number> {
    return this.db.transaction('rw', this.db.categories, this.db.transactions, async () => {
      const source = await this.db.categories.get(fromId)
      const target = await this.db.categories.get(toId)
      const targetParent = target?.parentId ? await this.db.categories.get(target.parentId) : undefined
      if (!source || source.parentId === null) throw new Error('待删除分类不存在')
      if (!target || target.parentId === null || target.disabled || !targetParent || targetParent.disabled || target.type !== source.type || target.id === source.id) throw new Error('迁移目标不存在或不可用')
      const records = await this.db.transactions.where('categoryId').equals(fromId).toArray()
      const now = new Date().toISOString()
      await this.db.transactions.bulkPut(records.map((item) => ({ ...item, categoryId: toId, updatedAt: now })))
      await this.db.categories.delete(fromId)
      return records.length
    })
  }

  async recentCategories(type: LedgerType, limit = 10): Promise<Category[]> {
    const categories = new Map((await this.listCategories({ type })).map((category) => [category.id, category]))
    const result: Category[] = []
    const seen = new Set<string>()
    for (const transaction of await this.listTransactions()) {
      const category = categories.get(transaction.categoryId)
      if (transaction.type !== type || !category || seen.has(category.id)) continue
      result.push(category)
      seen.add(category.id)
      if (result.length >= limit) break
    }
    return result
  }

  async getSettings(): Promise<AppSettings> {
    return JSON.parse(JSON.stringify((await this.db.settings.get('app'))?.value ?? DEFAULT_SETTINGS))
  }

  async putSettings(value: AppSettings): Promise<void> {
    await this.db.settings.put({ key: 'app', value: JSON.parse(JSON.stringify(value)) })
  }

  async exportSnapshot(): Promise<LedgerSnapshot> {
    return this.db.transaction('r', this.db.categories, this.db.transactions, this.db.settings, async () => ({
      schemaVersion: 1,
      categories: await this.db.categories.toArray(),
      transactions: await this.db.transactions.toArray(),
      settings: await this.getSettings(),
    }))
  }

  async replaceFromSnapshot(snapshot: LedgerSnapshot): Promise<void> {
    if (snapshot.schemaVersion !== 1) throw new Error('不支持的数据库版本')
    const categories = new Map(snapshot.categories.map((category) => [category.id, category]))
    if (snapshot.transactions.some((item) => categories.get(item.categoryId)?.type !== item.type)) throw new Error('备份包含无效分类引用')
    await this.db.transaction('rw', this.db.categories, this.db.transactions, this.db.settings, async () => {
      await this.db.transactions.clear()
      await this.db.categories.clear()
      await this.db.settings.clear()
      await this.db.categories.bulkAdd(JSON.parse(JSON.stringify(snapshot.categories)))
      await this.db.transactions.bulkAdd(JSON.parse(JSON.stringify(snapshot.transactions)))
      await this.db.settings.add({ key: 'app', value: JSON.parse(JSON.stringify(snapshot.settings)) })
    })
  }

  async resetAll(): Promise<void> {
    const { deviceId, licenseCode } = await this.getSettings()
    await this.replaceFromSnapshot({ schemaVersion: 1, categories: structuredClone([...DEFAULT_CATEGORIES]), transactions: [], settings: structuredClone({ ...DEFAULT_SETTINGS, deviceId, licenseCode }) })
  }

  async close(): Promise<void> {
    this.db.close()
  }

  async deleteDatabase(): Promise<void> {
    this.db.close()
    await Dexie.delete(this.db.name)
  }
}
