const SEED_TIME = '2026-01-01T00:00:00.000Z'

/**
 * 二级分类色板：同组内按 childIndex 轮转取色，保证同组二级颜色互不相同
 * （超过 12 个二级的组从头复用，如购物消费 17 个）。自定义二级没色时仍回退父色（见 category-color.ts）。
 */
const CHILD_COLOR_PALETTE: readonly string[] = ['#1677ff', '#ff7a45', '#8b5cf6', '#06b6d4', '#20a162', '#ef4444', '#eab308', '#ec4899', '#0ea5e9', '#14b8a6', '#a16207', '#7c3aed']

function buildCategory(id: string, name: string, icon: string, type: LedgerType, parentId: string | null, sortOrder: number, color?: string): Category {
  return {
    id,
    name,
    icon,
    type,
    parentId,
    isDefault: true,
    disabled: false,
    sortOrder,
    ...(color ? { color } : {}),
    createdAt: SEED_TIME,
    updatedAt: SEED_TIME,
  }
}

export const DEFAULT_CATEGORY_GROUPS: readonly CategoryGroup[] = SEED_GROUPS.map((group, groupIndex) => {
  const groupId = `preset-${group.type}-g${String(groupIndex + 1).padStart(2, '0')}`
  const parent = buildCategory(groupId, group.name, group.icon, group.type, null, groupIndex, group.color) as CategoryGroup
  parent.children = group.children.map((name, childIndex) =>
    buildCategory(`${groupId}-c${String(childIndex + 1).padStart(2, '0')}`, name, PRESET_ICON_BY_NAME[name] ?? group.icon, group.type, groupId, childIndex, CHILD_COLOR_PALETTE[childIndex % CHILD_COLOR_PALETTE.length]),
  )
  return parent
})

export const DEFAULT_CATEGORIES: readonly Category[] = DEFAULT_CATEGORY_GROUPS.flatMap((group) => {
  const { children, ...parent } = group
  return [parent, ...children]
})

export function categoriesForType(type: LedgerType, includeDisabled = false): CategoryGroup[] {
  return DEFAULT_CATEGORY_GROUPS
    .filter((group) => group.type === type)
    .map((group) => ({
      ...group,
      children: group.children.filter((child) => includeDisabled || !child.disabled),
    }))
}
