import { Capacitor, CapacitorHttp } from '@capacitor/core'

/**
 * 一次性激活码方案（阶段 3）：授权后端 API 客户端。
 *
 * 后端是阿里云 FC 函数（见 server/ 目录），三个接口：
 *   POST {baseUrl}/activate  { code, deviceId } → { ok, alreadyBound?, deviceId?, reason? }
 *   POST {baseUrl}/verify    { code, deviceId } → { ok, bound?, deviceId?, reason? }
 *   POST {baseUrl}/unbind    { code, deviceId } → { ok, wasBound?, reason? }（2026-09-07 新增：设备自助解绑）
 *
 * fetcher 注入模式与 release-manifest.ts 一致：
 *   - 原生平台（Android）默认走 CapacitorHttp（绕过 CORS 限制）
 *   - 网页默认走 fetch
 *   - 测试注入 fake fetcher，不真实联网
 */

export interface ActivateApiResponse {
  ok: boolean
  alreadyBound?: boolean
  deviceId?: string
  reason?: string
}

export interface UnbindApiResponse {
  ok: boolean
  wasBound?: boolean
  reason?: string
}

export interface VerifyApiResponse {
  ok: boolean
  bound?: boolean
  deviceId?: string
  reason?: string
}

/** 激活/校验请求体 */
export interface LicenseApiRequest {
  code: string
  deviceId: string
}

export class LicenseApiError extends Error {
  constructor(
    message: string,
    /** 服务端返回的机器可读原因（not_in_ledger / revoked / used_by_other …），网络/服务故障时为 undefined */
    readonly reason: string | undefined,
  ) {
    super(message)
    this.name = 'LicenseApiError'
  }
}

/** 网络层故障（超时、断网、DNS、非 2xx）统一抛这个 —— 激活场景必须联网，UI 要提示 */
export class LicenseNetworkError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'LicenseNetworkError'
  }
}

const TIMEOUT_MS = 15_000

function resolveBaseUrl(): string {
  return (import.meta.env.VITE_LICENSE_API_URL ?? '').trim().replace(/\/$/, '')
}

/**
 * POST 一个 JSON 请求到授权后端，解析 JSON 响应。
 * 网络故障 / 非 2xx / 响应不是 JSON → 抛 LicenseNetworkError。
 */
async function postJson(
  path: 'activate' | 'verify' | 'unbind',
  body: LicenseApiRequest,
  fetcher?: typeof fetch,
  baseUrlOverride?: string,
): Promise<Record<string, unknown>> {
  const baseUrl = (baseUrlOverride ?? resolveBaseUrl()).trim().replace(/\/$/, '')
  if (!baseUrl) throw new LicenseNetworkError('授权服务未配置，请联系作者')
  const url = `${baseUrl}/${path}`

  let response: Response
  try {
    if (fetcher) {
      // 测试注入的 fetcher：直接用，带超时
      const controller = new AbortController()
      const timer = setTimeout(() => controller.abort(), TIMEOUT_MS)
      try {
        response = await fetcher(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
          signal: controller.signal,
        })
      } finally {
        clearTimeout(timer)
      }
    } else if (Capacitor.isNativePlatform()) {
      // 原生平台：CapacitorHttp 不受 WebView CORS 约束（与 release-manifest.ts 同模式）
      const result = await CapacitorHttp.request({
        url,
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        data: body,
        connectTimeout: TIMEOUT_MS,
        readTimeout: TIMEOUT_MS,
      })
      if (result.status < 200 || result.status >= 300) throw new Error(`HTTP ${result.status}`)
      return (typeof result.data === 'string' ? JSON.parse(result.data) : result.data) as Record<string, unknown>
    } else {
      // 网页：fetch + 超时
      const controller = new AbortController()
      const timer = setTimeout(() => controller.abort(), TIMEOUT_MS)
      try {
        response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
          signal: controller.signal,
        })
      } finally {
        clearTimeout(timer)
      }
    }
  } catch (cause) {
    if (cause instanceof LicenseNetworkError) throw cause
    throw new LicenseNetworkError('无法连接授权服务器，请检查网络后重试')
  }

  if (!response.ok) {
    // 4xx/5xx：尝试读 body 里的 reason（后端 JSON 错误），读不到按网络层处理
    try {
      const data = (await response.json()) as Record<string, unknown>
      if (typeof data.reason === 'string') return data
    } catch { /* body 不是 JSON，走下面的统一报错 */ }
    throw new LicenseNetworkError(`授权服务器返回 ${response.status}`)
  }
  try {
    return (await response.json()) as Record<string, unknown>
  } catch {
    throw new LicenseNetworkError('授权服务器响应格式异常')
  }
}

/** 调用 POST /activate：激活并绑定设备。失败（业务原因）抛 LicenseApiError。baseUrlOverride 仅测试注入用。 */
export async function requestActivate(body: LicenseApiRequest, fetcher?: typeof fetch, baseUrlOverride?: string): Promise<ActivateApiResponse> {
  const data = await postJson('activate', body, fetcher, baseUrlOverride)
  if (data.ok !== true) {
    throw new LicenseApiError(humanizeReason(data.reason), typeof data.reason === 'string' ? data.reason : undefined)
  }
  return { ok: true, alreadyBound: data.alreadyBound === true, deviceId: typeof data.deviceId === 'string' ? data.deviceId : body.deviceId }
}

/** 调用 POST /verify：检查更新时的授权复查（失败仅提示、不阻断）。baseUrlOverride 仅测试注入用。 */
export async function requestVerify(body: LicenseApiRequest, fetcher?: typeof fetch, baseUrlOverride?: string): Promise<VerifyApiResponse> {
  const data = await postJson('verify', body, fetcher, baseUrlOverride)
  return {
    ok: data.ok === true,
    bound: data.bound === true,
    deviceId: typeof data.deviceId === 'string' ? data.deviceId : undefined,
    reason: typeof data.reason === 'string' ? data.reason : undefined,
  }
}

/** 调用 POST /unbind：设备自助解绑（联网清台账绑定，2026-09-07）。失败（业务原因）抛 LicenseApiError。baseUrlOverride 仅测试注入用。 */
export async function requestUnbind(body: LicenseApiRequest, fetcher?: typeof fetch, baseUrlOverride?: string): Promise<UnbindApiResponse> {
  const data = await postJson('unbind', body, fetcher, baseUrlOverride)
  if (data.ok !== true) {
    throw new LicenseApiError(humanizeReason(data.reason), typeof data.reason === 'string' ? data.reason : undefined)
  }
  return { ok: true, wasBound: data.wasBound === true }
}

/** 把后端 reason 翻译成用户能看懂的话（与 LicensePage 文案统一，阶段 4 复用） */
export function humanizeReason(reason: unknown): string {
  switch (reason) {
    case 'not_in_ledger': return '非法授权码，请联系作者获取授权码。'
    case 'revoked': return '授权码已停用，请联系作者。'
    case 'used_by_other': return '授权码已绑定其他设备：请先在原设备上解绑（授权页→解绑授权码），或联系作者处理。'
    case 'device_mismatch': return '只有绑定的设备才能解绑此授权码'
    case 'expired':
    case 'expired_in_ledger': return '授权码已超过有效期，请联系作者续期。'
    case 'invalid_signature': return '授权码校验不通过：可能复制不完整，请从作者发的消息里重新完整复制。'
    case 'invalid_format': return '授权码格式不对：请完整复制作者发的授权码，注意别带多余空格或换行。'
    case 'invalid_payload':
    case 'parse_error': return '授权码内容无效：可能复制不完整，请从作者发的消息里重新完整复制。'
    default: return '授权验证失败，请稍后重试'
  }
}
