import type { LedgerType } from './category'

export interface AppSettings {
  schemaVersion: 1
  currency: 'CNY'
  firstDayOfWeek: 1
  deviceId?: string
  licenseCode?: string
  lastBackupAt?: string
  /** 备份提醒开关：未备份流水超过阈值时在首页显示横幅（缺省视为开启） */
  backupReminderEnabled?: boolean
  /** 未备份流水达到该数量时首页显示提醒横幅（1~100） */
  backupReminderThreshold?: number
  lastSelectedCategoryIds?: Partial<Record<LedgerType, string>>
}

/** 未备份流水默认阈值 */
export const DEFAULT_BACKUP_REMINDER_THRESHOLD = 50

/** 备份提醒阈值的合法范围（用户可在设置里改） */
export const BACKUP_REMINDER_THRESHOLD_MIN = 1
export const BACKUP_REMINDER_THRESHOLD_MAX = 100

/** 取出一个合法的阈值（缺省或越界时回退到默认值） */
export function resolveBackupReminderThreshold(value: number | undefined): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return DEFAULT_BACKUP_REMINDER_THRESHOLD
  const rounded = Math.round(value)
  if (rounded < BACKUP_REMINDER_THRESHOLD_MIN) return BACKUP_REMINDER_THRESHOLD_MIN
  if (rounded > BACKUP_REMINDER_THRESHOLD_MAX) return BACKUP_REMINDER_THRESHOLD_MAX
  return rounded
}

export const DEFAULT_SETTINGS: AppSettings = {
  schemaVersion: 1,
  currency: 'CNY',
  firstDayOfWeek: 1,
  backupReminderEnabled: true,
}
