import nacl from 'tweetnacl'
import type { LicensePayload, LicenseStatus } from '@/domain/models/license'
import type { MoneyRepository } from '@/infrastructure/storage/repository'
import { fromBase64Url } from './base64url'
import { ensureDeviceId } from './device-id'
import { LICENSE_PUBLIC_KEY } from './license-public-key'
import { LicenseApiError, LicenseNetworkError, requestActivate, requestUnbind } from './license-api'

function parsePayload(encoded: string): LicensePayload {
  let payload: LicensePayload
  try {
    payload = JSON.parse(new TextDecoder().decode(fromBase64Url(encoded))) as LicensePayload
  } catch (cause) {
    // atob 对含非法字符的字符串抛 InvalidCharacterError（message 英文 "The string contains invalid characters."），
    // 上面一并吞掉：只要是从非英文码的 base64url 解码失败，给一个统一的中文文案
    throw new Error('授权码格式不对：请完整复制作者发的授权码，注意别带多余空格或换行。')
  }
  if (payload.v !== 2 || typeof payload.i !== 'number') throw new Error('授权码版本或内容无效，请检查是否复制完整')
  if (payload.e !== undefined && typeof payload.e !== 'number') throw new Error('授权码过期时间无效')
  return payload
}

/**
 * 兜底：把库/运行时的英文异常翻译成统一的中文文案（V1.0.39）。
 * - atob 抛 InvalidCharacterError（"The string contains invalid characters."）
 * - tweetnacl 抛 TypeError（"bad signature size"）
 * - JSON.parse 抛 SyntaxError（"Unexpected token … in JSON"）
 * 这些都是用户"输入了不完整或格式错的授权码"的体现，统一提示完整复制。
 */
function humanizeRuntimeError(error: unknown): string {
  if (!(error instanceof Error) || !error.message) return '授权码格式不对：请完整复制作者发的授权码，注意别带多余空格或换行。'
  const message = error.message
  const hasNonAscii = /[^\x00-\x7F]/.test(message)
  if (hasNonAscii) return message // 已是中文，原样透传
  return '授权码格式不对：请完整复制作者发的授权码，注意别带多余空格或换行。'
}

/**
 * 离线验证授权码：只验签名和有效期，不绑定设备（2026-08-28 起取消设备指纹绑定）。
 * 早期绑设备的旧码兼容处理：签名合法即放行，忽略其中的 d 字段。
 *
 * 2026-09-05 起叠加在线台账（阶段 3）：本函数仍是「本地第一道关」，
 * 联网激活/校验状态由 activateLicense / verifyLicenseOnline 负责。
 */
export function verifyLicenseCode(code: string, now = new Date(), publicKey = LICENSE_PUBLIC_KEY): LicenseStatus {
  const [payloadText, signatureText, extra] = code.trim().split('.')
  if (!payloadText || !signatureText || extra) return { kind: 'invalid', reason: '授权码格式不对：请完整复制作者发的授权码，注意别带多余空格或换行。' }
  try {
    const signature = fromBase64Url(signatureText)
    if (signature.length !== 64) return { kind: 'invalid', reason: '授权码校验不通过：可能复制不完整，请从作者发的消息里重新完整复制。' } // Ed25519 签名固定 64 字节（与 server/lib/verify.js 一致）
    const valid = nacl.sign.detached.verify(new TextEncoder().encode(payloadText), signature, fromBase64Url(publicKey))
    if (!valid) return { kind: 'invalid', reason: '授权码校验不通过：可能复制不完整，请从作者发的消息里重新完整复制。' }
    const payload = parsePayload(payloadText)
    if (payload.e !== undefined && now.getTime() > payload.e) return { kind: 'expired', expiresAt: new Date(payload.e).toISOString() }
    return { kind: 'active', payload }
  } catch (error) {
    return { kind: 'invalid', reason: humanizeRuntimeError(error) }
  }
}

export async function currentLicenseStatus(repository: Pick<MoneyRepository, 'getSettings' | 'putSettings'>, now = new Date()): Promise<LicenseStatus> {
  const settings = await repository.getSettings()
  if (!settings.licenseCode) return { kind: 'unactivated' }
  return verifyLicenseCode(settings.licenseCode, now)
}

/**
 * 激活授权码（阶段 3 联网化）：本地验签/有效期 → 联网 POST /activate 绑定本机 deviceId。
 *
 * 分支约定（与计划文档一致）：
 * - 本地验签失败/过期：直接判定，不联网
 * - 联网后端拒绝（未登记/已作废/已被其他设备绑定）：返回 invalid（带人类可读文案）
 * - 网络失败：**不落库**，返回 invalid（提示需联网激活），用户联网后重试即可
 * - 成功（含本机重复激活幂等 alreadyBound）：写入 settings.licenseCode
 *
 * @param fetcher 测试注入的 fetch 实现（不传则按平台选 CapacitorHttp/fetch）
 */
export async function activateLicense(
  repository: Pick<MoneyRepository, 'getSettings' | 'putSettings'>,
  code: string,
  _now = new Date(),
  fetcher?: typeof fetch,
  apiBaseUrl?: string,
): Promise<LicenseStatus> {
  const trimmed = code.trim()
  // 1) 本地第一道关：签名/有效期
  const status = verifyLicenseCode(trimmed)
  if (status.kind !== 'active') return status

  // 2) 联网绑定设备
  const deviceId = await ensureDeviceId(repository)
  try {
    await requestActivate({ code: trimmed, deviceId }, fetcher, apiBaseUrl)
  } catch (cause) {
    if (cause instanceof LicenseNetworkError) {
      // network 标记：UI 据此弹 toast 强提醒（V1.0.38），而不是只在按钮上方留一行小字
      return { kind: 'invalid', reason: '无法连接授权服务器。请确认手机已联网（Wi-Fi 或蜂窝数据），然后重试。', network: true }
    }
    const apiError = cause as LicenseApiError
    return { kind: 'invalid', reason: apiError.message || '授权验证失败' }
  }

  // 3) 联网通过才落库
  const settings = await repository.getSettings()
  await repository.putSettings({ ...settings, licenseCode: trimmed })
  return status
}

/**
 * 解绑授权（2026-09-07 改联网版）：先联网清台账绑定，成功后才清本机授权记录。
 * - 未激活（本机没有授权码）：直接清本机残留，不联网
 * - 已激活：POST /unbind（后端校验只有绑定的设备才能解绑）→ 成功才清本机
 * - 断网/服务故障：解绑失败，保留绑定（本机和台账一致）
 * 返回 null 表示成功；字符串为用户可读的失败原因。
 */
export async function deactivateLicense(
  repository: Pick<MoneyRepository, 'getSettings' | 'putSettings'>,
  fetcher?: typeof fetch,
  apiBaseUrl?: string,
): Promise<string | null> {
  const settings = await repository.getSettings()
  if (!settings.licenseCode) {
    // 本机本来就没有授权码，无台账可清
    return null
  }
  try {
    const deviceId = await ensureDeviceId(repository)
    await requestUnbind({ code: settings.licenseCode, deviceId }, fetcher, apiBaseUrl)
  } catch (cause) {
    if (cause instanceof LicenseNetworkError) {
      return '解绑需要联网，请检查网络后重试'
    }
    const apiError = cause as LicenseApiError
    // 用户已明确确认解绑：服务端若明确判定授权码无效、作废、过期或不在台账，
    // 仍允许清除本机残留，避免失效授权把用户锁在无法操作的状态。
    if (apiError.reason) {
      const { licenseCode: _licenseCode, ...rest } = await repository.getSettings()
      await repository.putSettings(rest)
      return null
    }
    return apiError.message || '解绑失败，请稍后重试'
  }
  const { licenseCode: _licenseCode, ...rest } = await repository.getSettings()
  await repository.putSettings(rest)
  return null
}
