import { computed, markRaw, ref } from 'vue'
import { defineStore } from 'pinia'
import type { Category } from '@/domain/models/category'
import type { LicenseStatus } from '@/domain/models/license'
import { DEFAULT_SETTINGS, type AppSettings } from '@/domain/models/settings'
import type { TransactionRecord } from '@/domain/models/transaction'
import { currentLicenseStatus } from '@/infrastructure/licensing/license-service'
import { ensureDeviceId } from '@/infrastructure/licensing/device-id'
import { getMoneyRepository } from '@/infrastructure/storage/create-repository'

export const useAppStore = defineStore('app', () => {
  // Repository instances own database connections and mutable driver state; Vue must not proxy them.
  const repository = markRaw(getMoneyRepository())
  const loading = ref(true)
  const initialized = ref(false)
  const error = ref<string>()
  const categories = ref<Category[]>([])
  const transactions = ref<TransactionRecord[]>([])
  const license = ref<LicenseStatus>({ kind: 'unactivated' })
  const settings = ref<AppSettings>({ ...DEFAULT_SETTINGS })
  const revision = ref(0)
  const toast = ref<{ message: string; type: 'success' | 'error' | 'info' }>()
  let toastTimer: ReturnType<typeof setTimeout> | undefined

  const canWrite = computed(() => license.value.kind === 'active')

  async function initialize(): Promise<void> {
    if (initialized.value) return
    loading.value = true
    error.value = undefined
    try {
      // 热更新重载后旧的原生数据库连接可能尚未释放，首次 initialize 可能瞬时失败；自动重试一次即可恢复
      try {
        await repository.initialize()
      } catch {
        await new Promise((resolve) => setTimeout(resolve, 800))
        await repository.initialize()
      }
      await refresh()
      // 一次性激活码方案（阶段 2）：确保本机 deviceId 存在，激活/检查更新联网时上报用
      await ensureDeviceId(repository)
      await refresh()
      license.value = await currentLicenseStatus(repository)
      initialized.value = true
    } catch (cause) {
      error.value = cause instanceof Error ? cause.message : '本地数据初始化失败'
    } finally {
      loading.value = false
    }
  }

  async function refresh(): Promise<void> {
    const [nextCategories, nextTransactions, nextSettings] = await Promise.all([
      repository.listCategories({ includeDisabled: true }),
      repository.listTransactions(),
      repository.getSettings(),
    ])
    categories.value = nextCategories
    transactions.value = nextTransactions
    settings.value = nextSettings
    revision.value += 1
  }

  async function refreshLicense(): Promise<void> {
    license.value = await currentLicenseStatus(repository)
  }

  /**
   * 只更新内存中的授权状态，不改写本地授权码。
   * 授权码属于用户数据，只有授权页的主动解绑流程才允许清除。
   */
  function markLicenseInvalid(reason: string): void {
    license.value = { kind: 'invalid', reason }
  }

  async function updateSettings(patch: Partial<AppSettings>): Promise<void> {
    settings.value = { ...settings.value, ...patch }
    await repository.putSettings(settings.value)
  }

  function notify(message: string, type: 'success' | 'error' | 'info' = 'info'): void {
    if (toastTimer) clearTimeout(toastTimer)
    toast.value = { message, type }
    toastTimer = setTimeout(() => { toast.value = undefined }, 2000)
  }

  return { repository, loading, initialized, error, categories, transactions, settings, license, revision, toast, canWrite, initialize, refresh, refreshLicense, markLicenseInvalid, updateSettings, notify }
})
