import type { MoneyRepository } from '@/infrastructure/storage/repository'

/**
 * 获取（必要时生成并持久化）本机设备 ID。
 *
 * 用途：一次性激活码方案的设备绑定（阶段 2）。
 * - 首次调用：生成 UUID 存入 settings.deviceId
 * - 后续调用：直接返回已有值（重启/升级均不变）
 * - 与备份/恢复无关：backup.ts 已把 deviceId 排除在便携备份之外，恢复别的机器的备份不会覆盖本机 deviceId
 *
 * @returns 形如 "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx" 的 UUID 字符串
 */
export async function ensureDeviceId(repository: Pick<MoneyRepository, 'getSettings' | 'putSettings'>): Promise<string> {
  const settings = await repository.getSettings()
  if (settings.deviceId && isUuid(settings.deviceId)) return settings.deviceId
  const deviceId = crypto.randomUUID()
  await repository.putSettings({ ...settings, deviceId })
  return deviceId
}

/** 校验 UUID 格式（v4 形态，8-4-4-4-12），非法数据（如旧版本脏数据）时重新生成 */
export function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)
}
