import { CapacitorSQLite, SQLiteConnection, type SQLiteDBConnection } from '@capacitor-community/sqlite'
import type { Category, LedgerType } from '@/domain/models/category'
import { DEFAULT_SETTINGS, type AppSettings } from '@/domain/models/settings'
import type { TransactionRecord } from '@/domain/models/transaction'
import { DEFAULT_CATEGORIES } from '@/domain/services/category-seed'
import type { LedgerSnapshot, MoneyRepository } from './repository'

const DB_NAME = 'money_app'
const DB_VERSION = 3

interface SqlCategoryRow {
  id: string
  name: string
  icon: string
  type: LedgerType
  parent_id: string | null
  is_default: number
  disabled: number
  sort_order: number
  color: string | null
  created_at: string
  updated_at: string
}

interface SqlTransactionRow {
  id: string
  type: LedgerType
  amount_cents: number
  category_id: string
  booked_at: string
  note: string
  created_at: string
  updated_at: string
}

function toCategory(row: SqlCategoryRow): Category {
  return {
    id: row.id,
    name: row.name,
    icon: row.icon,
    type: row.type,
    parentId: row.parent_id,
    isDefault: row.is_default === 1,
    disabled: row.disabled === 1,
    sortOrder: row.sort_order,
    ...(row.color ? { color: row.color } : {}),
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  }
}

function toTransaction(row: SqlTransactionRow): TransactionRecord {
  return { id: row.id, type: row.type, amountCents: row.amount_cents, categoryId: row.category_id, bookedAt: row.booked_at, note: row.note ?? '', createdAt: row.created_at, updatedAt: row.updated_at }
}

export class NativeSqliteMoneyRepository implements MoneyRepository {
  private readonly sqlite = new SQLiteConnection(CapacitorSQLite)
  private db?: SQLiteDBConnection
  private transactionActive = false

  private connection(): SQLiteDBConnection {
    if (!this.db) throw new Error('数据库尚未初始化')
    return this.db
  }

  private async openConnection(): Promise<void> {
    const exists = await this.sqlite.isConnection(DB_NAME, false)
    this.db = exists.result
      ? await this.sqlite.retrieveConnection(DB_NAME, false)
      : await this.sqlite.createConnection(DB_NAME, false, 'no-encryption', DB_VERSION, false)
    if (!(await this.db.isDBOpen()).result) await this.db.open()
  }

  async initialize(): Promise<void> {
    try {
      await this.openConnection()
    } catch {
      // 热更新重载后 JS 上下文重建，插件原生侧的同名连接可能仍存在导致 createConnection 失败；
      // 关闭遗留连接后整条链路重建一次
      await this.sqlite.closeConnection(DB_NAME, false).catch(() => undefined)
      await this.openConnection()
    }
    await this.connection().execute('PRAGMA foreign_keys = ON;', false)
    await this.connection().execute(`
      CREATE TABLE IF NOT EXISTS categories (
        id TEXT PRIMARY KEY NOT NULL,
        name TEXT NOT NULL,
        icon TEXT NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('income','expense')),
        parent_id TEXT NULL REFERENCES categories(id),
        is_default INTEGER NOT NULL,
        disabled INTEGER NOT NULL,
        sort_order INTEGER NOT NULL,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_categories_type_parent ON categories(type, parent_id);
      CREATE TABLE IF NOT EXISTS transactions (
        id TEXT PRIMARY KEY NOT NULL,
        type TEXT NOT NULL CHECK(type IN ('income','expense')),
        amount_cents INTEGER NOT NULL CHECK(amount_cents > 0),
        category_id TEXT NOT NULL REFERENCES categories(id),
        booked_at TEXT NOT NULL,
        note TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
      CREATE INDEX IF NOT EXISTS idx_transactions_booked ON transactions(booked_at DESC);
      CREATE INDEX IF NOT EXISTS idx_transactions_category ON transactions(category_id);
      CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
    `)
    // 老版本迁移：v1 → v2（加 categories.color 列）、v2 → v3（内置二级分类补预设色）。
    // 幂等：PRAGMA table_info 检测列存在避免重复 ALTER；回填只写 color IS NULL 的行，用户改过的色不会被覆盖
    const columns = await this.connection().query(`PRAGMA table_info(categories)`)
    const hasColor = (columns.values ?? []).some((row) => String(row.name) === 'color')
    if (!hasColor) {
      await this.connection().execute(`ALTER TABLE categories ADD COLUMN color TEXT`)
    }
    // 给现有内置分类回填预设色：v1 老库补一级+二级，v2 库只补还空着的二级
    for (const preset of DEFAULT_CATEGORIES) {
      if (preset.color) {
        await this.run(`UPDATE categories SET color = ? WHERE id = ? AND color IS NULL`, [preset.color, preset.id])
      }
    }
    const count = await this.connection().query('SELECT COUNT(*) AS count FROM categories')
    if (Number(count.values?.[0]?.count ?? 0) === 0) {
      await this.inTransaction(async () => {
        for (const category of DEFAULT_CATEGORIES) await this.putCategory(category)
        await this.putSettings(DEFAULT_SETTINGS)
      })
    }
  }

  private async inTransaction<T>(action: () => Promise<T>): Promise<T> {
    const db = this.connection()
    if (this.transactionActive) return action()
    await db.beginTransaction()
    this.transactionActive = true
    try {
      const result = await action()
      await db.commitTransaction()
      return result
    } catch (error) {
      await db.rollbackTransaction()
      throw error
    } finally {
      this.transactionActive = false
    }
  }

  private async run(statement: string, values: unknown[] = []): Promise<void> {
    // The native plugin starts its own transaction by default. Disable that
    // behavior while an explicit batch transaction is active to avoid nesting.
    await this.connection().run(statement, values, !this.transactionActive)
  }

  async listTransactions(): Promise<TransactionRecord[]> {
    const result = await this.connection().query('SELECT * FROM transactions ORDER BY booked_at DESC')
    return (result.values ?? []).map((row) => toTransaction(row as SqlTransactionRow))
  }

  async getTransaction(id: string): Promise<TransactionRecord | undefined> {
    const result = await this.connection().query('SELECT * FROM transactions WHERE id = ?', [id])
    return result.values?.[0] ? toTransaction(result.values[0] as SqlTransactionRow) : undefined
  }

  async putTransaction(value: TransactionRecord): Promise<void> {
    const category = await this.getCategory(value.categoryId)
    if (!category || category.parentId === null || category.type !== value.type) throw new Error('账单必须选择同类型的有效二级分类')
    await this.run(
      `INSERT INTO transactions(id,type,amount_cents,category_id,booked_at,note,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)
       ON CONFLICT(id) DO UPDATE SET type=excluded.type,amount_cents=excluded.amount_cents,category_id=excluded.category_id,booked_at=excluded.booked_at,note=excluded.note,updated_at=excluded.updated_at`,
      [value.id, value.type, value.amountCents, value.categoryId, value.bookedAt, value.note, value.createdAt, value.updatedAt],
    )
  }

  async deleteTransaction(id: string): Promise<void> { await this.run('DELETE FROM transactions WHERE id = ?', [id]) }
  async clearTransactions(): Promise<void> { await this.run('DELETE FROM transactions') }

  async listCategories(options: { type?: LedgerType; includeDisabled?: boolean } = {}): Promise<Category[]> {
    const clauses: string[] = []
    const values: unknown[] = []
    if (options.type) { clauses.push('type = ?'); values.push(options.type) }
    if (!options.includeDisabled) clauses.push('disabled = 0')
    const where = clauses.length ? ` WHERE ${clauses.join(' AND ')}` : ''
    const result = await this.connection().query(`SELECT * FROM categories${where} ORDER BY is_default DESC, sort_order ASC`, values)
    return (result.values ?? []).map((row) => toCategory(row as SqlCategoryRow))
  }

  async getCategory(id: string): Promise<Category | undefined> {
    const result = await this.connection().query('SELECT * FROM categories WHERE id = ?', [id])
    return result.values?.[0] ? toCategory(result.values[0] as SqlCategoryRow) : undefined
  }

  async putCategory(value: Category): Promise<void> {
    if (value.parentId) {
      const parent = await this.getCategory(value.parentId)
      if (!parent || parent.parentId !== null || parent.type !== value.type) throw new Error('所属分类组不存在或类型不一致')
    }
    await this.run(
      `INSERT INTO categories(id,name,icon,type,parent_id,is_default,disabled,sort_order,color,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)
       ON CONFLICT(id) DO UPDATE SET name=excluded.name,icon=excluded.icon,type=excluded.type,parent_id=excluded.parent_id,is_default=excluded.is_default,disabled=excluded.disabled,sort_order=excluded.sort_order,color=excluded.color,updated_at=excluded.updated_at`,
      [value.id, value.name, value.icon, value.type, value.parentId, value.isDefault ? 1 : 0, value.disabled ? 1 : 0, value.sortOrder, value.color ?? null, value.createdAt, value.updatedAt],
    )
  }

  async deleteCategory(id: string): Promise<void> {
    const tx = await this.connection().query('SELECT COUNT(*) AS count FROM transactions WHERE category_id = ?', [id])
    if (Number(tx.values?.[0]?.count ?? 0) > 0) throw new Error('该分类仍有流水，不能直接删除')
    const children = await this.connection().query('SELECT COUNT(*) AS count FROM categories WHERE parent_id = ?', [id])
    if (Number(children.values?.[0]?.count ?? 0) > 0) throw new Error('请先处理一级分类下的二级分类')
    await this.run('DELETE FROM categories WHERE id = ?', [id])
  }

  async clearCustomCategories(): Promise<number> {
    return this.inTransaction(async () => {
      const result = await this.connection().query('SELECT id FROM categories WHERE is_default = 0')
      const ids = (result.values ?? []).map((row) => String(row.id))
      let referenced = 0
      for (const id of ids) {
        const count = await this.connection().query('SELECT COUNT(*) AS count FROM transactions WHERE category_id = ?', [id])
        referenced += Number(count.values?.[0]?.count ?? 0)
      }
      if (referenced > 0) throw new Error(`有 ${referenced} 条流水仍在使用自定义分类，请逐个迁移后再删除`)
      await this.run('DELETE FROM categories WHERE is_default = 0 AND parent_id IS NOT NULL')
      await this.run('DELETE FROM categories WHERE is_default = 0')
      return ids.length
    })
  }

  async migrateTransactionsAndDelete(fromId: string, toId: string): Promise<number> {
    return this.inTransaction(async () => {
      const source = await this.getCategory(fromId)
      const target = await this.getCategory(toId)
      const targetParent = target?.parentId ? await this.getCategory(target.parentId) : undefined
      if (!source || source.parentId === null) throw new Error('待删除分类不存在')
      if (!target || target.parentId === null || target.disabled || !targetParent || targetParent.disabled || target.type !== source.type || target.id === source.id) throw new Error('迁移目标不存在或不可用')
      const count = await this.connection().query('SELECT COUNT(*) AS count FROM transactions WHERE category_id = ?', [fromId])
      await this.run('UPDATE transactions SET category_id = ?, updated_at = ? WHERE category_id = ?', [toId, new Date().toISOString(), fromId])
      await this.run('DELETE FROM categories WHERE id = ?', [fromId])
      return Number(count.values?.[0]?.count ?? 0)
    })
  }

  async recentCategories(type: LedgerType, limit = 10): Promise<Category[]> {
    const result = await this.connection().query(
      `SELECT c.* FROM transactions t JOIN categories c ON c.id=t.category_id WHERE t.type=? AND c.disabled=0 GROUP BY t.category_id ORDER BY MAX(t.booked_at) DESC LIMIT ?`,
      [type, limit],
    )
    return (result.values ?? []).map((row) => toCategory(row as SqlCategoryRow))
  }

  async getSettings(): Promise<AppSettings> {
    const result = await this.connection().query(`SELECT value FROM settings WHERE key='app'`)
    return result.values?.[0]?.value ? JSON.parse(String(result.values[0].value)) as AppSettings : structuredClone(DEFAULT_SETTINGS)
  }

  async putSettings(value: AppSettings): Promise<void> {
    await this.run(`INSERT INTO settings(key,value) VALUES('app',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value`, [JSON.stringify(value)])
  }

  async exportSnapshot(): Promise<LedgerSnapshot> {
    return { schemaVersion: 1, categories: await this.listCategories({ includeDisabled: true }), transactions: await this.listTransactions(), settings: await this.getSettings() }
  }

  async replaceFromSnapshot(snapshot: LedgerSnapshot): Promise<void> {
    if (snapshot.schemaVersion !== 1) throw new Error('不支持的数据库版本')
    const categories = new Map(snapshot.categories.map((category) => [category.id, category]))
    if (snapshot.transactions.some((item) => categories.get(item.categoryId)?.type !== item.type)) throw new Error('备份包含无效分类引用')
    await this.inTransaction(async () => {
      await this.run('DELETE FROM transactions')
      await this.run('DELETE FROM categories')
      await this.run('DELETE FROM settings')
      const categories = [...snapshot.categories].sort((a, b) => Number(a.parentId !== null) - Number(b.parentId !== null) || a.sortOrder - b.sortOrder)
      for (const category of categories) await this.putCategory(category)
      for (const transaction of snapshot.transactions) await this.putTransaction(transaction)
      await this.putSettings(snapshot.settings)
    })
  }

  async resetAll(): Promise<void> {
    const { deviceId, licenseCode } = await this.getSettings()
    await this.replaceFromSnapshot({ schemaVersion: 1, categories: structuredClone([...DEFAULT_CATEGORIES]), transactions: [], settings: structuredClone({ ...DEFAULT_SETTINGS, deviceId, licenseCode }) })
  }

  async close(): Promise<void> {
    if (!this.db) return
    await this.db.close()
    await this.sqlite.closeConnection(DB_NAME, false)
    this.db = undefined
  }
}
